// The question bank the app reads.
//
// Do not edit this file or questions.json by hand. Questions are authored in
// the .txt files in this directory (one per line, pipe-delimited) and compiled
// with `npm run compile`, which validates and de-duplicates them.
//
// The bank is FETCHED rather than bundled. Past a couple of thousand questions
// inlining it would push the JS bundle over half a megabyte, delaying first
// paint for everyone. As a separate asset it is cached independently, so a
// code change does not force users to re-download the whole bank.

import { BANK_VERSION } from "./bank-version.js";

const bank = [];

let pending = null;

/**
 * Populates the bank in place and resolves once ready.
 * Filling the existing array (rather than reassigning) means every module that
 * imported `bank` sees the data without needing to re-import.
 */
export function loadBank() {
  if (bank.length) return Promise.resolve(bank);

  // Single-file builds (the shareable demo) inline the bank on the page,
  // because a sandboxed artifact cannot fetch a sibling asset.
  if (typeof window !== "undefined" && Array.isArray(window.__QUESTIONS__)) {
    bank.push(...window.__QUESTIONS__);
    return Promise.resolve(bank);
  }

  if (pending) return pending;

  // ?v= is the bank's content hash, so a redeploy that adds questions busts
  // the cache while an unchanged bank keeps being served from it.
  const url = `${import.meta.env.BASE_URL}questions.json?v=${BANK_VERSION}`;
  pending = fetch(url)
    .then((res) => {
      if (!res.ok) throw new Error(`${res.status} loading question bank`);
      return res.json();
    })
    .then((questions) => {
      bank.push(...questions);
      return bank;
    })
    .catch((err) => {
      pending = null; // allow a retry
      throw err;
    });

  return pending;
}

/**
 * How the bank's size is described in the UI.
 *
 * Rounded down to the nearest hundred and marked with a "+", so the figure is
 * honest without reading as a target to finish. Derived from the bank itself,
 * so adding questions moves it without anyone remembering to edit a number.
 */
export function bankBlurb() {
  // Callers render this; an empty bank means it was read before loadBank()
  // resolved. Say nothing rather than advertise "0 quizzes".
  if (!bank.length) return "Thousands of quizzes";
  if (bank.length < 100) return `${bank.length} quizzes`;
  return `${Math.floor(bank.length / 100) * 100}+ quizzes`;
}

export default bank;
